const fs = require('fs');
const html = fs.readFileSync(process.argv[2],'utf8');
const m = html.match(/<script>([\s\S]*)<\/script>/);
fs.writeFileSync('/tmp/ashfall_extract.js', m[1]);
console.log('extracted', m[1].length, 'chars');
